def balanced_brackets(text):
    pairs = {')': '(', ']': '[', '}': '{'}
    opens = set('([{')
    stack = []
    for ch in text:
        if ch in opens:
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack[-1] != pairs[ch]:
                return False
            stack.pop()
    return not stack

